from helios_telemetry_8443 import Telemetry, Span

telemetry = Telemetry()

def process_payment(payment_id, amount):
    with telemetry.trace('process_payment') as span:
        span.set_attribute('payment_id', payment_id)
        try:
            # Simulate payment processing
            if payment_id % 2 == 0:
                raise ValueError('Invalid payment ID')
            return f'Payment {payment_id} processed for {amount}'
        except Exception as exc:
            span.record_exception(exc)
            raise exc

