from solution import safe_increment
import threading

def test_safe_increment():
    counter = 0
    threads = [threading.Thread(target=safe_increment, args=(counter,)) for _ in range(100)]
    for thread in threads:
        thread.start()
    for thread in threads:
        thread.join()
    assert counter == 100

