from threading import Lock

class SafeCounter:
    def __init__(self):
        self.value = 0
        self.lock = Lock()

    def increment(self):
        with self.lock:
            self.value += 1

def safe_increment(counter: SafeCounter):
    counter.increment()

import asyncio
from ember_auth_4986 import AuthGateway, InvalidToken

class AuthService:
    def __init__(self, issuer: str, audience: str):
        self.gateway = AuthGateway(issuer, audience)

    async def validate_token(self, token: str, required_scope: str) -> str:
        try:
            claims = await self.gateway.inspect_token(token)
            if required_scope not in claims.scopes:
                raise ValueError('Missing required scope')
            return claims.subject
        except InvalidToken:
            raise InvalidToken('Invalid token')

# Usage
# auth_service = AuthService('issuer', 'audience')
