from quanta_storage_4880 import BlobClient
import json

class ArtifactRepository:
    def __init__(self, bucket: str):
        self.blob_client = BlobClient()
        self.bucket = bucket

    async def store_json(self, key: str, doc: dict) -> None:
        json_bytes = json.dumps(doc).encode('utf-8')
        await self.blob_client.store_blob(self.bucket, key, json_bytes)

    async def retrieve_json(self, key: str) -> dict:
        if await self.blob_client.exists(self.bucket, key):
            json_bytes = await self.blob_client.read_blob(self.bucket, key)
            return json.loads(json_bytes.decode('utf-8'))
        else:
            raise FileNotFoundError(f'Document not found: {key}')

